<?php
declare(strict_types=1);

namespace App;

/**
 * One-time passwords for the admin panel.
 *
 * - "activation" codes are stored hashed in `setup_tokens` (survive restarts,
 *   generated by the installer for the very first login);
 * - "login" codes live in the server-side session only and expire quickly.
 * The plain code is never written to the database and never logged.
 */
final class Otp
{
    private const MAX_ATTEMPTS = 5;

    public static function generateCode(): string
    {
        return str_pad((string) random_int(0, 99999999), 8, '0', STR_PAD_LEFT);
    }

    private static function hash(string $code): string
    {
        return hash_hmac('sha256', $code, (string) Config::get('APP_KEY', 'fallback-key'));
    }

    /* ------------------------------------------------------ first login code */

    /** @return array{code:string, expires_at:string} */
    public static function createActivationCode(?int $adminId = null, int $ttlMinutes = 1440): array
    {
        $code = self::generateCode();
        $expires = gmdate('Y-m-d H:i:s', time() + max(5, $ttlMinutes) * 60);
        Db::insert('setup_tokens', [
            'admin_id'   => $adminId,
            'token_hash' => self::hash($code),
            'purpose'    => 'first_login',
            'expires_at' => $expires,
            'created_at' => now_utc(),
        ]);
        return ['code' => $code, 'expires_at' => $expires];
    }

    /**
     * Check a first-login activation code and burn it on success.
     * Returns the token row id, or null when invalid / expired / already used.
     */
    public static function consumeActivationCode(string $code, ?int $adminId = null): ?int
    {
        $code = trim($code);
        if (!preg_match('/^\d{6,10}$/', $code)) {
            return null;
        }
        $rows = Db::all(
            "SELECT id, token_hash FROM setup_tokens
             WHERE purpose = 'first_login' AND used_at IS NULL AND expires_at > ?
               AND (admin_id IS NULL OR admin_id = ?)",
            [now_utc(), $adminId ?? 0]
        );
        foreach ($rows as $row) {
            if (hash_equals((string) $row['token_hash'], self::hash($code))) {
                Db::update('setup_tokens', ['used_at' => now_utc()], 'id = ?', [(int) $row['id']]);
                return (int) $row['id'];
            }
        }
        return null;
    }

    /* -------------------------------------------------------- login 2nd step */

    /** @return array{delivery:string, masked:string} */
    public static function issueForLogin(int $adminId): array
    {
        $code = self::generateCode();
        $ttl = max(2, min(30, Settings::int('otp_ttl_minutes', 10)));
        unset($_SESSION['otp']);
        $_SESSION['otp'] = [
            'hash'     => self::hash($code),
            'exp'      => time() + $ttl * 60,
            'attempts' => 0,
            'admin_id' => $adminId,
        ];

        $delivery = Settings::get('otp_delivery', 'bale');
        $chatId = trim(Settings::get('otp_chat_id'));
        $sent = false;

        if ($delivery === 'bale' && $chatId !== '') {
            $sent = self::deliverViaBale($code, $chatId);
        }

        if (!$sent) {
            // Local fallback: code on the server, readable by the owner only.
            self::deliverToFile($code, $adminId, $chatId === '' ? 'no-chat-id' : 'bale-unreachable');
            $delivery = 'file';
        }

        Settings::set('otp_last_request_at', now_utc());
        Settings::flush();

        return [
            'delivery' => $delivery,
            'masked'   => $chatId !== '' ? self::maskChat($chatId) : '—',
        ];
    }

    public static function verifyLoginCode(?string $code): bool
    {
        $otp = $_SESSION['otp'] ?? null;
        if (!is_array($otp)) {
            return false;
        }
        if ((int) $otp['exp'] < time()) {
            unset($_SESSION['otp']);
            return false;
        }
        $otp['attempts'] = (int) $otp['attempts'] + 1;
        $_SESSION['otp'] = $otp;
        if ($otp['attempts'] > self::MAX_ATTEMPTS) {
            unset($_SESSION['otp']);
            Log::warn('OTP brute force detected', ['admin_id' => $otp['admin_id'] ?? null, 'ip' => client_ip()]);
            return false;
        }
        $code = trim((string) $code);
        if (!preg_match('/^\d{6,10}$/', $code)) {
            return false;
        }
        if (hash_equals((string) $otp['hash'], self::hash($code))) {
            unset($_SESSION['otp']);
            return true;
        }
        return false;
    }

    public static function pendingAdminId(): ?int
    {
        $otp = $_SESSION['otp'] ?? null;
        return is_array($otp) && (int) $otp['exp'] >= time() ? (int) $otp['admin_id'] : null;
    }

    private static function maskChat(string $chatId): string
    {
        $len = strlen($chatId);
        return $len <= 4 ? str_repeat('•', $len) : substr($chatId, 0, 3) . str_repeat('•', max(2, $len - 5)) . substr($chatId, -2);
    }

    private static function deliverViaBale(string $code, string $chatId): bool
    {
        try {
            $client = Bale::fromSettings();
            if (!$client->isConfigured()) {
                return false;
            }
            $text = "🔐 کد ورود به پنل مدیریت\n\nکد یکبار مصرف: {$code}\n\n"
                . 'اعتبار: ' . Settings::int('otp_ttl_minutes', 10) . " دقیقه\n"
                . 'اگر شما درخواست نداده‌اید این پیام را نادیده بگیرید.';
            $res = $client->sendMessage($chatId, $text);
            return (bool) ($res['ok'] ?? false);
        } catch (\Throwable $e) {
            Log::warn('OTP delivery via Bale failed: ' . $e->getMessage());
            return false;
        }
    }

    private static function deliverToFile(string $code, int $adminId, string $reason): void
    {
        $dir = APP_ROOT . '/storage/otp';
        if (!is_dir($dir)) {
            @mkdir($dir, 0770, true);
        }
        $file = $dir . '/otp.log';
        $line = sprintf(
            "[%s] admin=%d ip=%s delivery=file reason=%s code=%s\n",
            gmdate('c'),
            $adminId,
            client_ip(),
            $reason,
            $code
        );
        if (@file_put_contents($file, $line, FILE_APPEND | LOCK_EX) !== false) {
            @chmod($file, 0600);
        }
        Log::info('OTP generated (local delivery mode)', ['admin_id' => $adminId, 'reason' => $reason]);
    }
}
